# May 2025
# This R script rationalizes and rounds the figures/estimates created in the upstream R scripts so that they conform with the guidelines for the DfE 'Exploring
# Education Statistics' production platform system, where GLMS is published. This script covers two areas of GLMS, including graduate employment rates and graduate salaries 
# The Outputs generated by the script includes a data file and meta-file in CSV format for uploading on to the EES platform.


#######################
# Graduate breakdowns #
#######################

# Read in rds output files
Graduate_breakdowns_emp_original <- readRDS(paste0(filepath, data_folder, end_year, ".rds")) # This is just for a single year
Graduate_breakdowns_sal_original <- readRDS(paste0(filepath, data_folder, end_year, ".rds")) # This is just for a single year


## Grad employment

# Creates new columns for EES standards - time and geography
# Renames columns
Graduate_breakdowns_emp <- Graduate_breakdowns_emp_original %>%
  mutate(time_identifier = "Calendar year",
         geographic_level = "National",
         country_code = "E92000001",
         country_name = "England",
         time_period = "2024") %>%
  rename(graduate_characteristic = Population,
         graduate_breakdown = Breakdown,
         hs_employment_rate = HSemployment_rate,
         hs_employed_sample = HSemployed_sample,
         hs_employment_accuracy_flag = HSemployment_accuracy_flag,
         hs_employment_suppression_flag = HSemployment_suppression_flag,
         hs_employment_empty_flag = HSemployment_empty_flag)

# Makes all column names lower case
colnames(Graduate_breakdowns_emp) <- tolower(colnames(Graduate_breakdowns_emp))

# Ungroups data (that was previously grouped using group_by function)
# Filters out all cases wheregraduate type is not in scope
Graduate_breakdowns_emp <- Graduate_breakdowns_emp %>%
  ungroup() %>% 
  filter(!graduate_breakdown == "NA",
         !graduate_breakdown == "Other",
         !graduate_breakdown == "Pass",
         !graduate_breakdown == "Dont Know")


# Tweak the name of the accuracy flag to something more descriptive / useful for users - applied March 2025
Graduate_breakdowns_emp <- Graduate_breakdowns_emp %>%
mutate(employment_rate_accuracy = employment_accuracy_flag) %>%
mutate(hs_employment_rate_accuracy = hs_employment_accuracy_flag) %>%  
mutate(unemployment_rate_accuracy = unemployment_accuracy_flag) %>%  
mutate(inactivity_rate_accuracy = inactive_accuracy_flag) %>%  
mutate(employment_rate_suppression = employment_suppression_flag) %>%
mutate(hs_employment_rate_suppression = hs_employment_suppression_flag) %>%  
mutate(unemployment_rate_suppression = unemployment_suppression_flag) %>%  
mutate(inactivity_rate_suppression = inactive_suppression_flag) %>%  

  # Select the variables needed and reorder
# Graduate_breakdowns_emp <- Graduate_breakdowns_emp %>%
  select("time_period",
         "time_identifier",
         "geographic_level",
         "country_code",
         "country_name",
         "graduate_characteristic",
         "graduate_breakdown",
         "employment_rate",
         "hs_employment_rate",
         "unemployment_rate",
         "inactivity_rate",
         "employment_rate_accuracy",
         "hs_employment_rate_accuracy",
         "unemployment_rate_accuracy",
         "inactivity_rate_accuracy",
         "employment_rate_suppression",
         "hs_employment_rate_suppression",
         "unemployment_rate_suppression",
         "inactivity_rate_suppression",
         "employment_empty_flag",
         "hs_employment_empty_flag",
         "unemployment_empty_flag",
         "inactive_empty_flag")



# Multiplies rates by 100 and rounds to one decimal place
Graduate_breakdowns_emp <- Graduate_breakdowns_emp %>%
  mutate(employment_rate = employment_rate*100) %>%
  mutate(hs_employment_rate = hs_employment_rate*100) %>%
  mutate(unemployment_rate = unemployment_rate*100) %>% 
  mutate(inactivity_rate = inactivity_rate*100) %>%
  mutate(employment_rate = formatC(employment_rate, digits = 1, format = "f")) %>%
  mutate(hs_employment_rate = formatC(hs_employment_rate, digits = 1, format = "f")) %>%
  mutate(unemployment_rate = formatC(unemployment_rate, digits = 1, format = "f")) %>%
  mutate(inactivity_rate = formatC(inactivity_rate, digits = 1, format = "f"))

Graduate_breakdowns_emp <- Graduate_breakdowns_emp %>%
  mutate(graduate_breakdown = recode(graduate_breakdown,
                                     "Equality Act Disabled" = "Disabled",
                                     "Not Equality Act Disabled" = "Not Disabled",
                                     "Asian / Asian British"= "Asian or Asian British",
                                     "Black / African / Caribbean / Black British" = "Black or African or Caribbean or Black British",
                                     "Other ethnic group" = "Other Ethnic Group")) %>% 
  
  mutate(graduate_characteristic = recode(graduate_characteristic,
                                          "DEGCLS7" = "Degree Class",
                                          "DISEA" = "Disability",
                                          "ETHNICITY" = "Ethnicity",
                                          "SEX" = "Sex"))

# remove the suppression flag after checking that no rows need to be suppressed below
# if in the future any rows need suppressing, then keep these in and address in the same way that has been done in 8.3EES_part_time_2024.R
# Graduate_breakdowns_emp <- Graduate_breakdowns_emp %>%
#  select(-c(employment_rate_suppression, unemployment_rate_suppression,
#            inactivity_rate_suppression, hs_employment_rate_suppression,
#            employment_empty_flag, hs_employment_empty_flag,
#            unemployment_empty_flag, inactive_empty_flag))


readr::write_csv(Graduate_breakdowns_emp,
                 paste0(filepath, data_folder,end_year,".csv"))


# Make a table for the meta data

Graduate_breakdowns_emp.meta <- data.frame("col_name" = c("employment_rate",
                                                          "hs_employment_rate",
                                                          "unemployment_rate",
                                                          "inactivity_rate",
                                                          "graduate_characteristic",
                                                          "graduate_breakdown"),
                                           "col_type" = c("Indicator",
                                                          "Indicator",
                                                          "Indicator",
                                                          "Indicator",
                                                          "Filter",
                                                          "Filter"),
                                           "label" = c("Employment rate",
                                                       "High-skilled employment rate",
                                                       "Unemployment rate",
                                                       "Inactivity rate",
                                                       "Graduate characteristic",
                                                       "Graduate breakdown"),
                                           "indicator_grouping" = c("","","","","",""),
                                           "indicator_unit" = c("%","%","%","%","",""),
                                           "indicator_dp"= c("1","1", "1","1","",""),
                                           "filter_hint" = c("","","","","Select the Graduate characteristic you are interested in","Select the Graduate breakdown you are interested in"),
                                           "filter_grouping_column"=c("","","","","",""))


readr::write_csv(Graduate_breakdowns_emp.meta,
                 paste0(filepath, data_folder,end_year,".meta.csv"))











### Salaries


# Creates new columns for EES standards - time and geography
# Renames columns
Graduate_breakdowns_sal <- Graduate_breakdowns_sal_original %>%
  mutate(time_identifier = "Calendar year",
         geographic_level = "National",
         country_code = "E92000001",
         country_name = "England",
         time_period = 2024,) %>%
  rename(graduate_group = Group,
         graduate_breakdown = Value,
         industry_to_recode = Industry)
 #        sex=gender) # change from gender to sex for conistency with the LFS variable extracted

# Makes all column names lower case
colnames(Graduate_breakdowns_sal) <- tolower(colnames(Graduate_breakdowns_sal))




# Recode, cleans the name of industries
Graduate_breakdowns_sal <- Graduate_breakdowns_sal %>%
  mutate(graduate_group = recode(graduate_group, 
                                 "Graduates: 16-64" = "Graduate 16-64",
                                 "Graduates: 21-30" = "Graduate 21-30")) %>%
  
  mutate(graduate_breakdown = recode(graduate_breakdown,
                                     "C -Manufacturing" = "Manufacturing",
                                     "F - Construction" = "Construction",
                                     "G,I -Distribution, hotels and restaurants" = "Distribution or Hotels or Restaurants",
                                     "H,J -Transport and communication" = "Transport and Communication",
                                     "K,L,M,N - Banking and finance" = "Banking and Finance",
                                     "O,P,Q - Public admin, education and health" = "Public Admin or Education or Health", 
                                     "A - Agriculture, forestry and fishing" = "Agriculture, Forestry and Fishing",
                                     "B,D,E - Energy and water" = "Energy and Water", 
                                     "R,S,T,U - Other services" = "Other Services")) %>% 
  
  mutate(industry_to_recode = recode(industry_to_recode,
                                     "C -Manufacturing" = "Manufacturing",
                                     "F - Construction" = "Construction",
                                     "G,I -Distribution, hotels and restaurants" = "Distribution or Hotels or Restaurants",
                                     "H,J -Transport and communication" = "Transport and Communication",
                                     "K,L,M,N - Banking and finance" = "Banking and Finance",
                                     "O,P,Q - Public admin, education and health" = "Public Admin or Education or Health",
                                     "A - Agriculture, forestry and fishing" = "Agriculture, Forestry and Fishing",
                                     "B,D,E - Energy and water" = "Energy and Water", 
                                     "R,S,T,U - Other services" = "Other Services")) # %>%                            


# Removes categories we don't report on - these exclusions were removed for conformance with GLMS 2022 outputs in June 2024
#  filter(graduate_breakdown!="A - Agriculture, forestry and fishing") %>% 
#  filter(graduate_breakdown!="B,D,E - Energy and water") %>% 
#  filter(graduate_breakdown!="R,S,T,U - Other services") %>% 

#  filter(is.na(industry_to_recode) | industry_to_recode!="R,S,T,U - Other services") %>% 
#  filter(is.na(industry_to_recode) | industry_to_recode!="A - Agriculture, forestry and fishing") %>% 
#  filter(is.na(industry_to_recode) | industry_to_recode!="B,D,E - Energy and water")


# This recode creates two distinct variables for gender and industry
# This is because before they were split into two variables (given there are two breakdowns - gender and industry)
Graduate_breakdowns_sal <- Graduate_breakdowns_sal %>%
  mutate(gender = case_when(
    (graduate_breakdown == "Male") ~ "Male",
    (graduate_breakdown == "Female") ~ "Female",
    (graduate_breakdown != "Male" | graduate_breakdown != "Female") ~ "Total")) %>% 
  
  mutate(industry = case_when(
    (graduate_breakdown == "Manufacturing") ~ "Manufacturing",
    (graduate_breakdown == "Construction") ~ "Construction",
    (graduate_breakdown == "Distribution or Hotels or Restaurants") ~ "Distribution or Hotels or Restaurants",
    (graduate_breakdown == "Transport and Communication") ~ "Transport and Communication",
    (graduate_breakdown == "Banking and Finance") ~ "Banking and Finance",
    (graduate_breakdown == "Public Admin or Education or Health") ~ "Public Admin or Education or Health",
    (graduate_breakdown ==  "Agriculture, Forestry and Fishing") ~ "Agriculture, Forestry and Fishing",
    (graduate_breakdown ==  "Energy and Water") ~ "Energy and Water", 
    (graduate_breakdown ==  "Other Services") ~ "Other Services",
    
    
    TRUE ~ industry_to_recode))

# Renames NAs
Graduate_breakdowns_sal <- Graduate_breakdowns_sal %>%
  replace_na(list(industry = "All industries"))

# March 25 tweak -- Rename accuracy_flag to something more descriptive / useful i.e. median_salary_accuracy
Graduate_breakdowns_sal <- Graduate_breakdowns_sal %>%
mutate(median_salary_accuracy = accuracy_flag) %>%
mutate(median_salary_suppression = suppression_flag) %>%
mutate(sex = gender) %>%
    # str(Graduate_breakdown_sal)
#Select the variables needed
# Graduate_breakdowns_sal <- Graduate_breakdown_sal %>%
  select("time_period",
         "time_identifier",
         "geographic_level",
         "country_code",
         "country_name",
         "graduate_group" ,
        # "gender",
         "sex",
         "industry",
         "median",
         "median_salary_accuracy",
         "median_salary_suppression")
 #        "empty_flag")
# str(Graduate_breakdown_sal)


# Change Median salaries to be the yearly median salary, then Round up the median salaries to the nearest £500
Graduate_breakdowns_sal <- Graduate_breakdowns_sal %>%
  mutate(median = ifelse(leap_year(time_period), median*366/7, median*365/7)) %>%
  mutate(p = median%%500) %>%  
  mutate(rd_up = median+500-p) %>% #Numbers for rounding up
  mutate(rd_down = median-p) %>%   #Numbers for rounding down
  mutate(median = ifelse(500-p<=p,rd_up,rd_down))

# apply suppression process below: This is required for some sectors where 
# sample counts were low or sample counts were they were zero need to add in a empty row for completeness
Graduate_breakdowns_sal <- Graduate_breakdowns_sal %>%
  mutate(median = ifelse(median_salary_suppression == 1, "c", median))

